private string Evaluate(string title, string employer, string location, string arrangement, string description, string payMin, string payMax, string skillsRequired, string skillsMissing, string setting1, string setting2, string setting3, out string note)
{
    note = "";
    if (setting1.Trim().Length == 0 || arrangement.Trim().ToLowerInvariant() == "remote")
        return "pass";
    var where = location.Trim();
    if (where.Length == 0)
    {
        note = "the posting does not state a location";
        return "flag";
    }
    var lower = where.ToLowerInvariant();
    var places = setting1.Split(',');
    for (var i = 0; i < places.Length; i++)
    {
        var place = places[i].Trim().ToLowerInvariant();
        if (place.Length > 0 && lower.Contains(place, StringComparison.Ordinal))
            return "pass";
    }
    note = "located in " + where;
    return "exclude";
}
